class Solution {
    public int[] windowPeaks(int[] temps, int k) {
        int[] out = new int[temps.length - k + 1];
        for (int i = 0; i + k <= temps.length; i++) {
            int peak = temps[i];
            for (int j = i; j < i + k; j++) peak = Math.max(peak, temps[j]);
            out[i] = peak;
        }
        return out;
    }
}

