int* windowPeaks(int* temps, int tempsSize, int k, int* returnSize) {
    int m = tempsSize - k + 1;
    int* out = malloc(m * sizeof(int));
    for (int i = 0; i < m; i++) {
        int peak = temps[i];
        for (int j = i; j < i + k; j++) if (temps[j] > peak) peak = temps[j];
        out[i] = peak;
    }
    *returnSize = m;
    return out;
}

