class Solution:
    def windowPeaks(self, temps: List[int], k: int) -> List[int]:
        n = len(temps)
        from_start, to_end = temps[:], temps[:]
        for i in range(1, n):
            if i % k:
                from_start[i] = max(from_start[i - 1], temps[i])
        for i in range(n - 2, -1, -1):
            if (i + 1) % k:
                to_end[i] = max(to_end[i + 1], temps[i])
        return [max(to_end[i], from_start[i + k - 1]) for i in range(n - k + 1)]

