class Solution {
    public int[] windowPeaks(int[] temps, int k) {
        int n = temps.length;
        int[] fromStart = temps.clone(), toEnd = temps.clone();
        for (int i = 1; i < n; i++) if (i % k != 0) fromStart[i] = Math.max(fromStart[i - 1], temps[i]);
        for (int i = n - 2; i >= 0; i--) if ((i + 1) % k != 0) toEnd[i] = Math.max(toEnd[i + 1], temps[i]);
        int[] out = new int[n - k + 1];
        for (int i = 0; i + k <= n; i++) out[i] = Math.max(toEnd[i], fromStart[i + k - 1]);
        return out;
    }
}

