from collections import deque

class Solution:
    def windowPeaks(self, temps: List[int], k: int) -> List[int]:
        dq, out = deque(), []
        for i, v in enumerate(temps):
            while dq and temps[dq[-1]] <= v:
                dq.pop()
            dq.append(i)
            if dq[0] <= i - k:
                dq.popleft()
            if i >= k - 1:
                out.append(temps[dq[0]])
        return out

