class Solution {
    public int[] windowPeaks(int[] temps, int k) {
        int n = temps.length;
        int[] dq = new int[n], out = new int[n - k + 1];
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++) {
            while (tail > head && temps[dq[tail - 1]] <= temps[i]) tail--;
            dq[tail++] = i;
            if (dq[head] <= i - k) head++;
            if (i >= k - 1) out[i - k + 1] = temps[dq[head]];
        }
        return out;
    }
}

