class Solution {
public:
    vector<int> windowPeaks(vector<int>& temps, int k) {
        deque<int> dq;
        vector<int> out;
        for (int i = 0; i < (int) temps.size(); i++) {
            while (!dq.empty() && temps[dq.back()] <= temps[i]) dq.pop_back();
            dq.push_back(i);
            if (dq.front() <= i - k) dq.pop_front();
            if (i >= k - 1) out.push_back(temps[dq.front()]);
        }
        return out;
    }
};

